import { format_Date, formatTime } from "@/JsonFiles/DateFormate.js";
import { list_all_organizations_swipes } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import AddDatacorrection from "@/components/PresenceApp/PopUps/AddDatacorrection.vue";
import html2canvas from "html2canvas";
import CreateExternalTicketDialog from "@/components/Tickets/CreateExternalTicketDialog.vue";
export default {
  components: {
    AddDatacorrection,
    CreateExternalTicketDialog,
    SnackBar
  },
  data() {
    return {
      search: "",
      searchQuery: "",
      sortBy: [{
        key: "datacorrected_correct_on",
        order: "desc"
      }],
      tableLoading: false,
      tableData: [],
      SnackBarComponent: {},
      componentCheck: 0,
      datacorrectionDialog: false,
      fixed: true,
      next_token: null,
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      headers: [{
        title: "Member Name/ID",
        value: "user_name",
        sortable: true,
        align: "start"
      }, {
        title: "Location",
        value: "location_name",
        sortable: true,
        align: "start"
      }, {
        title: "Corrected For",
        value: "swiped_time",
        sortable: true,
        align: "start"
      }, {
        title: "Corrected On",
        value: "datacorrected_correct_on",
        sortable: true,
        align: "start"
      }, {
        title: "Approved By",
        value: "datacorrected_by",
        sortable: true,
        align: "start"
      }, {
        title: "Comments",
        value: "datacorrected_comments",
        sortable: true,
        align: "start"
      }],
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      // Screenshot Values
      DialogCreateExternalTicket: false,
      ScreenshotFile: null,
      orgDetails: {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      }
    };
  },
  created() {
    this.windowHeight = window.innerHeight - 250;
    this.get_data_correction();
  },
  watch: {
    currentPage(newVal, oldVal) {
      // When the page changes, check if we need to load more data
      if (newVal > oldVal && this.next_token) {
        // User is going to next page and we have more data to load
        this.get_data_correction();
      } else {
        // Just scroll to top of table for same page or going back
        const table = document.querySelector(".modern-data-table");
        if (table) table.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }
    }
  },
  computed: {
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  methods: {
    async TakeScreenshot() {
      const target = document.body;
      const canvas = await html2canvas(target, {
        scale: window.devicePixelRatio || 2,
        useCORS: true,
        logging: false,
        windowWidth: document.documentElement.scrollWidth,
        windowHeight: document.documentElement.scrollHeight
      });
      const dataUrl = canvas.toDataURL("image/png");
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], "screenshot.png", {
        type: "image/png"
      });
      this.ScreenshotFile = file;
      this.DialogCreateExternalTicket = true;
    },
    DialogCreateExternalTicketEmit() {
      this.DialogCreateExternalTicket = false;
    },
    back_action() {
      this.$store.commit("SetattendenceBack", true);
      this.$router.push("/home/UserLevel");
    },
    add_data_correction() {
      this.componentCheck = 1;
      this.datacorrectionDialog = true;
    },
    get_swipe_pagination() {
      if (this.next_token) {
        this.get_data_correction();
      }
    },
    get_date(val) {
      return format_Date(val / 1000);
      // const d = new Date(parseInt(val));
      // var date = d.getDate().toLocaleString();
      // var month = (d.getMonth() + 1).toLocaleString();
      // var year = d.getFullYear();

      // return (
      //   (+date <= 9 ? "0" + date : date) +
      //   "/" +
      //   (+month <= 9 ? "0" + month : month) +
      //   "/" +
      //   year
      // );
    },
    get_time(date) {
      return formatTime(date / 1000);

      // let a = new Date(date).toLocaleTimeString("en-In", {
      //   hour: "2-digit",
      //   minute: "2-digit",
      //   second: "2-digit",
      // });
      // return a.toUpperCase();
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.datacorrectionDialog = false;
      this.tableData = [];
      this.next_token = null;
      this.currentPage = 1;
      this.totalItems = 0;
      this.get_data_correction();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async get_data_correction() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;

      // Reset pagination if this is the first load (no next_token)
      if (!this.next_token) {
        this.currentPage = 1;
        this.totalItems = 0;
      }
      try {
        let result = await API.graphql(graphqlOperation(list_all_organizations_swipes, {
          input: {
            user_email_id: data.user.user_email_id,
            swipe_source: "DATACORRECTION",
            organization_id: data.organization.organization_id,
            limit: 100,
            nextToken: this.next_token
          }
        }));
        this.tableLoading = false;
        var response = result.data.list_all_organizations_swipes;
        if (response.Status == "SUCCESS") {
          this.next_token = response.nextToken;
          if (this.next_token) {
            // If we have more data, concatenate to existing array
            let array = this.tableData.concat(response.data);
            this.tableData = array;
          } else {
            // If no more data, concatenate what we have (don't replace)
            if (response.data && response.data.length > 0) {
              let array = this.tableData.concat(response.data);
              this.tableData = array;
            }
          }
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.swipe_id === obj.swipe_id));
          this.tableData = uniqueArrayOfObjects;

          // Update total items for pagination
          this.totalItems = this.tableData.length;
        } else {
          this.tableLoading = false;
        }

        // console.log(this.tableData);
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "user_name" || key === "member_id" || key === "location_name" || key === "datacorrected_by" || key === "datacorrected_comments") {
        return value.toLowerCase();
      }
      if (key === "swiped_time" || key === "datacorrected_correct_on") {
        return new Date(value).getTime();
      }
      return value;
    }
  }
};
